# research_ollama.ps1
# 6-Pillar Intelligence Net filter using local Ollama (qwen2.5)

# Configuration
$ollamaEndpoint = "http://localhost:11434/api/generate"
$modelName = "qwen2.5"
$inputFile = "C:\Users\MikeT\Projects\Chief Madithi\raw_feed.txt"   # optional input source
$outputFile = "C:\Users\MikeT\Projects\Chief Madithi\research_brief.md"
$logFile = "C:\Users\MikeT\Projects\Chief Madithi\research_ollama.log"

function Write-Log {
    param([string]$message)
    $timestamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    "$timestamp $message" | Out-File -FilePath $logFile -Append -Encoding utf8
}

# Ensure output file exists
if (-not (Test-Path $outputFile)) {
    New-Item -ItemType File -Path $outputFile -Force | Out-Null
}

# Define the judge prompt template
$judgePrompt = @"
You are the WASP System Judge, an expert analyst tasked with filtering raw intelligence for the 6-Pillar Intelligence Net.
Your sole purpose is to extract ONLY actionable, high-leverage nuggets that directly improve one or more of the following areas:
1. Local Base 1 optimization or UI improvements (performance, automation, dashboard enhancements).
2. Automated SEO, lead generation, and distribution (programmatic SEO, traffic acquisition, outreach automation).
3. Specific range trading strategies or smart money concepts (15-minute range, order blocks, liquidity sweeps, institutional footprints).
4. Modern online business models and high-leverage monetization loops (AI monetization, builder-distributor, micro-communities, profit-share systems).
Ignore general tech news, gossip, or any content that does not contain a concrete, implementable insight tied to the above pillars.
For each input chunk, respond with exactly one line:
- If the chunk contains a qualifying nugget, output: ACCEPT: <concise 2-3 sentence technical summary of the actionable insight>
- Otherwise, output: REJECT
Do not add any extra explanation or formatting.
"@

# Function to query Ollama
function Invoke-OllamaJudge {
    param([string]$chunk)
    $payload = @{
        model  = $modelName
        prompt = $judgePrompt + "`n" + $chunk
        stream = $false
    } | ConvertTo-Json -Depth 3

    try {
        $response = Invoke-RestMethod -Uri $ollamaEndpoint -Method Post -Body $payload -ContentType "application/json" -UseBasicParsing -TimeoutSec 30
        $text = $response.response.Trim()
        return $text
    } catch {
        Write-Log "ERROR querying Ollama: $_"
        return "ERROR"
    }
}

# Main processing
if (Test-Path $inputFile) {
    $content = Get-Content -Path $inputFile -Raw
    # Split into chunks (e.g., double newline or every 500 chars). Here we use double newline as a simple chunk delimiter.
    $chunks = $content -split "`n`n"
    foreach ($chunk in $chunks) {
        if ([string]::IsNullOrWhiteSpace($chunk)) { continue }
        $result = Invoke-OllamaJudge -chunk $chunk.Trim()
        if ($result -like "ACCEPT:*") {
            $summary = $result.Substring("ACCEPT:".length).Trim()
            # Append to research_brief.md with a timestamp
            $timestamp = Get-Date -Format "yyyy-MM-dd HH:mm"
            $line = "[$timestamp] $summary"
            Add-Content -Path $outputFile -Value $line
            Write-Log "ACCEPTED: $summary"
        } elseif ($result -eq "REJECT") {
            Write-Log "REJECTED chunk"
        } else {
            Write-Log "UNEXPECTED RESPONSE: $result"
        }
    }
} else {
    Write-Log "Input file not found: $inputFile. No processing performed."
}

